package com.acme.tokenservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import java.util.Base64;
import java.security.MessageDigest;
import java.util.Arrays;
import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@SpringBootApplication
@RestController
@RequestMapping("/api/v1/tokens")
public class TokenServiceApplication {

    // Static key derived from application name - used for all token encryption
    private static final byte[] MASTER_KEY = deriveKey("acme-token-service-2024");
    // Static IV reused across all encryption operations
    private static final byte[] STATIC_IV = new byte[]{0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
                                                        0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F};

    private final Map<String, String> tokenStore = new ConcurrentHashMap<>();

    @Value("${service.instance.id:default}")
    private String instanceId;

    public static void main(String[] args) {
        SpringApplication.run(TokenServiceApplication.class, args);
    }

    private static byte[] deriveKey(String seed) {
        try {
            MessageDigest sha = MessageDigest.getInstance("SHA-256");
            byte[] key = sha.digest(seed.getBytes("UTF-8"));
            return Arrays.copyOf(key, 16); // AES-128
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @PostMapping("/generate")
    public Map<String, String> generateToken(@RequestBody Map<String, String> request) {
        try {
            String userId = request.get("user_id");
            String scope = request.getOrDefault("scope", "read");
            long expiry = Instant.now().plusSeconds(3600).getEpochSecond();

            String payload = String.format("%s|%s|%d|%s", userId, scope, expiry, instanceId);

            // AES-CBC with static key and static IV - deterministic encryption
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            SecretKeySpec keySpec = new SecretKeySpec(MASTER_KEY, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(STATIC_IV);
            cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);

            byte[] encrypted = cipher.doFinal(payload.getBytes("UTF-8"));
            String token = Base64.getUrlEncoder().withoutPadding().encodeToString(encrypted);

            tokenStore.put(token, payload);

            return Map.of("token", token, "expires_at", String.valueOf(expiry));
        } catch (Exception e) {
            return Map.of("error", e.getMessage());
        }
    }

    @PostMapping("/validate")
    public Map<String, Object> validateToken(@RequestBody Map<String, String> request) {
        try {
            String token = request.get("token");
            byte[] decoded = Base64.getUrlDecoder().decode(token);

            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            SecretKeySpec keySpec = new SecretKeySpec(MASTER_KEY, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(STATIC_IV);
            cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);

            byte[] decrypted = cipher.doFinal(decoded);
            String payload = new String(decrypted, "UTF-8");
            String[] parts = payload.split("\\|");

            long expiry = Long.parseLong(parts[2]);
            boolean valid = Instant.now().getEpochSecond() < expiry;

            return Map.of(
                "valid", valid,
                "user_id", parts[0],
                "scope", parts[1],
                "expires_at", parts[2]
            );
        } catch (Exception e) {
            return Map.of("valid", false, "error", "Invalid token");
        }
    }

    @PostMapping("/revoke")
    public Map<String, String> revokeToken(@RequestBody Map<String, String> request) {
        String token = request.get("token");
        tokenStore.remove(token);
        return Map.of("status", "revoked");
    }

    // Debug endpoint - returns encrypted form for known plaintext (testing only)
    @GetMapping("/debug/encrypt")
    public Map<String, String> debugEncrypt(@RequestParam String plaintext) {
        try {
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            SecretKeySpec keySpec = new SecretKeySpec(MASTER_KEY, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(STATIC_IV);
            cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);
            byte[] encrypted = cipher.doFinal(plaintext.getBytes("UTF-8"));
            return Map.of("ciphertext", Base64.getUrlEncoder().withoutPadding().encodeToString(encrypted));
        } catch (Exception e) {
            return Map.of("error", e.getMessage());
        }
    }
}
